// --- 설정(원하면 환경변수나 이전 노드에서 주입 가능) ---
const THRESHOLD =
  Number($json.threshold ?? $env.LOW_STOCK_THRESHOLD ?? 10);

// 재고/수량/상품명 필드 키 후보
const KEY_STOCK  = ["재고", "수량", "stock", "quantity"];
const KEY_NAME   = ["상품명", "제품명", "name"];
const KEY_SKU    = ["SKU", "sku"];

// --- 입력 표준화: baserow 노드/HTTP 두 케이스 모두 지원 ---
const list = (items[0]?.json?.results && Array.isArray(items[0].json.results))
  ? items[0].json.results
  : items.map(i => i.json);

// 필드 접근 유틸 (row 또는 row.fields 모두 지원)
const pick = (row, keys) => {
  for (const k of keys) {
    if (row?.[k] != null && row[k] !== "") return row[k];
    if (row?.fields?.[k] != null && row.fields[k] !== "") return row.fields[k];
  }
  return undefined;
};

// 필터링
const low = list.filter(r => {
  const stock = Number(pick(r, KEY_STOCK));
  return Number.isFinite(stock) && stock <= THRESHOLD;
});

// 이메일 본문에서 쓰기 편하도록 최소 정보만 정리
const results = low.map((r, i) => ({
  name:  pick(r, KEY_NAME) ?? `품목${i+1}`,
  sku:   pick(r, KEY_SKU)  ?? "",
  stock: Number(pick(r, KEY_STOCK)),
  raw:   r, // 필요하면 원본도 유지
}));

return [{ json: { count: results.length, results } }];

const data = item || {};
const results = Array.isArray(data.results) ? data.results : [];

const pick = (row, keys) => {
  for (const k of keys) {
    if (row && row[k] != null && row[k] !== '') return row[k];
    if (row && row.fields && row.fields[k] != null && row.fields[k] !== '') return row.fields[k];
  }
  return '';
};

// "- 상품명 (SKU): 수량" 형태로 한 줄 만들기
const lines = results.map((r, idx) => {
  const name  = pick(r, ['상품명', '제품명', 'name']) || `품목${idx + 1}`;
  const sku   = pick(r, ['SKU', 'sku']);
  const stock = pick(r, ['재고', '수량']);

  // 예: "- 상품B: 7"
  return `- ${name}${sku ? ' (' + sku + ')' : ''}: ${stock}`;
});

const count   = results.length;
const subject = count > 0
  ? `저재고 ${count}건 – 재고 확인 요청`
  : `저재고 없음 – 재고 정상`;

const nowStr = $now.setZone('Asia/Seoul').toISO();

const body = count > 0
  // 다음 품목의 재고가 임계치(≤10개) 이하입니다.\n\n- 상품B: 7\n기준 시각: ...
  ? [
      '다음 품목의 재고가 10개 이하입니다.',
      '',
      ...lines,
    ].join('\n')
  : [
      '현재 저재고 품목이 없습니다.',
      `기준 시각: ${nowStr}`,
    ].join('\n');

return {
  to: 'iuandn64@gmail.com',
  subject,
  text: body,
  count,
};
